  mc6850: 'MC6850',
  '74hc00': '74HC00',
  '74hc04': '74HC04',
  '74hc08': '74HC08',
  '74hc32': '74HC32',
  '74hc74': '74HC74',
  '74hc138': '74HC138',
  '74hc245': '74HC245',
  '74hc373': '74HC373',
  '74hc374': '74HC374',
  '74hc595': '74HC595',
  '74ls373': '74LS373',
  'osc_can': 'OSC',
  'max232': 'MAX232',
  'rnet_sip': 'R-NET',
  // These three gained sidecars in the reconcile but not a DIP label, so they
